-- Systems from Zero, SQL track: the course schema (PostgreSQL 18).
--
-- A small card-payments company. Customers own accounts, accounts carry cards, cards pay
-- merchants, and every movement of money is a balanced journal in ledger_entries.
--
-- This file builds the database for the lab tests (Testcontainers, see CourseDb.kt). An exact
-- copy, env/postgres/course/schema.sql, builds database "course" for the psql Try-its when
-- env/postgres.yml starts with a new volume. Edit this file, then copy it there:
-- SeedFilesInSyncTest fails while the two differ. seed.sql (copied the same way) fills it
-- with a small, hand-checkable data set. env/postgres/load-big.sql builds a large copy of
-- the same tables in schema "big" for the index and EXPLAIN lessons.
--
-- Design choices the lessons talk about:
--   * money is bigint minor units (cents), never float or the money type
--   * every timestamp is timestamptz, and every range of time is half-open [from, to)
--   * text plus CHECK instead of varchar(n) or char(n)
--   * identity columns BY DEFAULT, so seed files can supply explicit ids
--   * only primary key and unique indexes: foreign key and query indexes come in the index lesson

CREATE EXTENSION IF NOT EXISTS btree_gist;   -- lets "=" on bigint sit inside a GiST key (temporal keys)

-- Merchant category codes: the ISO 18245 four-digit code and what it means.
CREATE TABLE mcc_codes (
    mcc          text PRIMARY KEY CHECK (mcc ~ '^[0-9]{4}$'),
    description  text NOT NULL
);

CREATE TABLE merchants (
    merchant_id   bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name          text NOT NULL,
    mcc           text NOT NULL REFERENCES mcc_codes,
    country_code  text NOT NULL CHECK (country_code ~ '^[A-Z]{2}$'),
    onboarded_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE customers (
    customer_id   bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    email         text NOT NULL UNIQUE,
    full_name     text NOT NULL,
    country_code  text NOT NULL CHECK (country_code ~ '^[A-Z]{2}$'),
    referred_by   bigint REFERENCES customers (customer_id),   -- NULL: nobody referred them
    created_at    timestamptz NOT NULL DEFAULT now(),
    CHECK (referred_by <> customer_id)
);

CREATE TABLE accounts (
    account_id    bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    kind          text NOT NULL CHECK (kind IN ('customer', 'merchant', 'internal')),
    customer_id   bigint REFERENCES customers,
    merchant_id   bigint REFERENCES merchants,
    currency      text NOT NULL DEFAULT 'USD' CHECK (currency ~ '^[A-Z]{3}$'),
    status        text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'frozen', 'closed')),
    balance_minor bigint NOT NULL DEFAULT 0,                    -- denormalized cache of SUM(ledger_entries)
    opened_at     timestamptz NOT NULL DEFAULT now(),
    CHECK ((kind = 'customer') = (customer_id IS NOT NULL)),
    CHECK ((kind = 'merchant') = (merchant_id IS NOT NULL))
);

CREATE TABLE cards (
    card_id     bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    account_id  bigint NOT NULL REFERENCES accounts,
    brand       text NOT NULL CHECK (brand IN ('visa', 'mastercard', 'amex')),
    pan_last4   text NOT NULL CHECK (pan_last4 ~ '^[0-9]{4}$'),   -- never store a full card number
    expires_on  date NOT NULL,
    status      text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'blocked', 'expired')),
    is_primary  boolean NOT NULL DEFAULT false
);
-- at most one primary card per account: a partial unique index
CREATE UNIQUE INDEX cards_one_primary_per_account ON cards (account_id) WHERE is_primary;

CREATE TABLE payments (
    payment_id    bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    payment_uid   uuid NOT NULL DEFAULT uuidv7() UNIQUE,      -- idempotency key, time-ordered (PG18)
    card_id       bigint NOT NULL REFERENCES cards,
    merchant_id   bigint NOT NULL REFERENCES merchants,
    amount_minor  bigint NOT NULL CHECK (amount_minor > 0),
    currency      text NOT NULL DEFAULT 'USD' CHECK (currency ~ '^[A-Z]{3}$'),
    status        text NOT NULL CHECK (status IN ('pending', 'succeeded', 'failed')),
    created_at    timestamptz NOT NULL,
    metadata      jsonb NOT NULL DEFAULT '{}',
    amount_major  numeric(21, 2) GENERATED ALWAYS AS (amount_minor / 100.0)   -- PG18: VIRTUAL by default
);

CREATE TABLE refunds (
    refund_id     bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    payment_id    bigint NOT NULL REFERENCES payments,
    amount_minor  bigint NOT NULL CHECK (amount_minor > 0),
    reason        text NOT NULL CHECK (reason IN ('customer_request', 'duplicate', 'fraud')),
    created_at    timestamptz NOT NULL
    -- "refunds of a payment never exceed its amount" spans rows, so no CHECK can say it
);

-- Double-entry ledger: all legs of one posting share a journal_id and sum to zero.
CREATE SEQUENCE journal_id_seq;
CREATE TABLE ledger_entries (
    entry_id      bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    journal_id    bigint NOT NULL,
    account_id    bigint NOT NULL REFERENCES accounts,
    payment_id    bigint REFERENCES payments,
    refund_id     bigint REFERENCES refunds,
    entry_type    text NOT NULL CHECK (entry_type IN ('deposit', 'payment', 'refund', 'withdrawal', 'fee')),
    amount_minor  bigint NOT NULL CHECK (amount_minor <> 0),   -- signed: + credit, - debit
    created_at    timestamptz NOT NULL,
    CHECK ((entry_type IN ('payment', 'refund')) = (payment_id IS NOT NULL)),
    CHECK ((entry_type = 'refund') = (refund_id IS NOT NULL))
);

-- Fees per merchant over time. PG18 temporal primary key: no two periods of one merchant overlap.
CREATE TABLE merchant_fee_schedules (
    merchant_id   bigint NOT NULL REFERENCES merchants,
    valid_during  tstzrange NOT NULL,
    fee_bps       int NOT NULL CHECK (fee_bps BETWEEN 0 AND 1000),   -- basis points: 290 = 2.90%
    PRIMARY KEY (merchant_id, valid_during WITHOUT OVERLAPS)
    -- before PG18: EXCLUDE USING gist (merchant_id WITH =, valid_during WITH &&)
);

CREATE TABLE login_events (
    event_id     bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    customer_id  bigint NOT NULL REFERENCES customers,
    occurred_at  timestamptz NOT NULL,
    success      boolean NOT NULL,
    ip           inet
);

-- A job queue for background work (the SKIP LOCKED lesson).
CREATE TABLE jobs (
    job_id     bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    kind       text NOT NULL CHECK (kind IN ('send_receipt', 'settle_merchant', 'fraud_review')),
    payload    jsonb NOT NULL,
    status     text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued', 'running', 'done', 'failed')),
    run_after  timestamptz NOT NULL DEFAULT now(),
    attempts   int NOT NULL DEFAULT 0,
    locked_by  text,
    locked_at  timestamptz
);
CREATE INDEX jobs_ready_idx ON jobs (run_after) WHERE status = 'queued';

-- A flat nightly file from a partner bank, loaded as-is: no keys, no constraints, lots of
-- repetition. The schema-design lesson finds the anomalies in it and normalizes it.
CREATE TABLE payments_export (
    payment_id       bigint,
    customer_email   text,
    customer_name    text,
    card_brand       text,
    card_last4       text,
    merchant_name    text,
    mcc              text,
    mcc_description  text,
    amount_minor     bigint,
    created_at       timestamptz
);
